from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    seen = [[False] * w for _ in range(h)]
    q = deque()

    for r in range(h):
        for c in range(w):
            if (r in (0, h-1) or c in (0, w-1)) and grid[r][c] == bg and not seen[r][c]:
                seen[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and not seen[nr][nc] and grid[nr][nc] == bg:
                seen[nr][nc] = True
                q.append((nr, nc))

    out = [row[:] for row in grid]
    holes = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] == bg and not seen[r][c]]
    if holes:
        for r, c in holes:
            out[r][c] = 4
        return out

    # When there is no enclosed background area, recolor solid rectangular
    # patches of the foreground color.
    color = next((v for row in grid for v in row if v != bg), None)
    if color is None:
        return out
    marked = set()
    for r0 in range(h):
        for c0 in range(w):
            if grid[r0][c0] != color:
                continue
            for r1 in range(r0 + 2, h):
                for c1 in range(c0, w):
                    if all(grid[r][c] == color
                           for r in range(r0, r1 + 1)
                           for c in range(c0, c1 + 1)):
                        # Keep only rectangles that cannot be extended.
                        extend_up = r0 > 0 and all(grid[r0-1][c] == color for c in range(c0,c1+1))
                        extend_down = r1+1 < h and all(grid[r1+1][c] == color for c in range(c0,c1+1))
                        extend_left = c0 > 0 and all(grid[r][c0-1] == color for r in range(r0,r1+1))
                        extend_right = c1+1 < w and all(grid[r][c1+1] == color for r in range(r0,r1+1))
                        if not (extend_up or extend_down or extend_left or extend_right):
                            marked.update((r,c) for r in range(r0,r1+1) for c in range(c0,c1+1))
    for r, c in marked:
        out[r][c] = 4
    return out
